$pick = static function( $value, $allowed, $default ) { return in_array( $value, $allowed, true ) ? $value : $default; }; $style = $pick( $a['style'] ?? 'solid', array( 'solid', 'outline', 'soft', 'text' ), 'solid' ); $size = $pick( $a['size'] ?? 'medium', array( 'small', 'medium', 'large' ), 'medium' ); $align = $pick( $a['align'] ?? 'left', array( 'left', 'center', 'right' ), 'left' ); $width = ( $a['width'] ?? 'auto' ) === 'full' ? 'full' : 'auto'; $icon = $pick( $a['icon'] ?? 'arrow', array( 'none', 'arrow', 'external' ), 'arrow' );
